import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.Ki30n65y.js";const n="/depgate/screenshots/ledger.png",s="/depgate/screenshots/ledger-detail.png",m=JSON.parse('{"title":"Decision Ledger","description":"","frontmatter":{},"headers":[],"relativePath":"admin/decision-ledger.md","filePath":"admin/decision-ledger.md"}'),d={name:"admin/decision-ledger.md"};function i(h,e,l,c,g,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="decision-ledger" tabindex="-1">Decision Ledger <a class="header-anchor" href="#decision-ledger" aria-label="Permalink to &quot;Decision Ledger&quot;">​</a></h1><p>The <strong>Decision Ledger</strong> records every download DepGate refused, and why. Use it to answer &quot;who tried to install this version, and which policy stopped it?&quot;, or to export blocks for a compliance report. Changes people make in DepGate are in the <a href="./audit-log">Audit Log</a>; allowed downloads are counted on the <a href="./dashboard">Dashboard</a>.</p><p>In the sidebar, choose <strong>Decision Ledger</strong>.</p><p><img src="'+n+'" alt="The Decision Ledger"></p><h2 id="what-is-recorded" tabindex="-1">What is recorded <a class="header-anchor" href="#what-is-recorded" aria-label="Permalink to &quot;What is recorded&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>When</th></tr></thead><tbody><tr><td><strong>Block · Enforce</strong></td><td>A policy, the malware list or namespace protection refused a download.</td></tr><tr><td><strong>Upstream unavailable</strong></td><td>The upstream registry timed out or refused the connection, so the client got <code>502</code> or <code>503</code>.</td></tr><tr><td><strong>Malware</strong></td><td>Any request for a package on the malware list, blocked or let through by an override or an exception. The row carries a <strong>Malware</strong> tag.</td></tr><tr><td><strong>Allow</strong></td><td>Only for malware that was let through. Ordinary allowed downloads are not stored one by one.</td></tr></tbody></table><p>What a policy in monitor mode would have blocked is on the <a href="./monitoring">Monitoring</a> page, not here.</p><p>Each row shows the time, the package with its version and ecosystem, the repository, the event, the policy that decided, the actor with their IP address, and the <strong>Build</strong> when a CI token carried build metadata. The actor is a person&#39;s email address, a service account, or a CI token&#39;s name.</p><h2 id="view-the-details" tabindex="-1">View the details <a class="header-anchor" href="#view-the-details" aria-label="Permalink to &quot;View the details&quot;">​</a></h2><p>Choose a row to expand it.</p><p><img src="'+s+'" alt="An expanded ledger entry for a blocked download"></p><ul><li><strong>Reasons</strong>: why the version was refused, for example the vulnerability and its CVSS score, or the license that is not approved.</li><li><strong>Request</strong>: the entry ID, the policy, the malware entry when one matched, the actor and their kind, the IP address, the client&#39;s user agent, how the request authenticated, and the metadata a CI token attached, such as the pull request and build number.</li></ul><h2 id="filter-and-search" tabindex="-1">Filter and search <a class="header-anchor" href="#filter-and-search" aria-label="Permalink to &quot;Filter and search&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Filter</th><th>Use it to</th></tr></thead><tbody><tr><td><strong>Search by package</strong></td><td>Find every decision for one package.</td></tr><tr><td>Time range</td><td>The last 24 hours, 7 days (the default), 30 days, or a custom range of days.</td></tr><tr><td><strong>Ecosystem</strong></td><td>One ecosystem.</td></tr><tr><td><strong>Event</strong></td><td><strong>Block · Enforce</strong>, <strong>Upstream unavailable</strong>, <strong>Malware (any outcome)</strong> or <strong>Allow (malware let through)</strong>.</td></tr><tr><td><strong>Repository</strong></td><td>Requests through one repository.</td></tr><tr><td><strong>Auth</strong></td><td>How the request authenticated: <strong>CI token</strong>, <strong>API key</strong>, <strong>Registry token</strong>, <strong>Password</strong>, <strong>OIDC</strong> or <strong>SAML</strong>.</td></tr><tr><td><strong>Policy</strong></td><td>Part of a policy name.</td></tr><tr><td><strong>Actor or IP</strong></td><td>An email address, a token name or an IP address.</td></tr><tr><td><strong>Metadata key=value</strong></td><td>CI token metadata, for example <code>pr_number=4821</code>.</td></tr></tbody></table><p><strong>Clear filters</strong> returns to the last 7 days.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Choose <strong>Export CSV</strong> to download the rows that match the current filters. An export stops after 10,000 rows and tells you; narrow the filters for the rest. To send blocks to a SIEM as they happen, use <a href="./log-streaming">Log streaming</a> or <a href="./webhooks">webhooks</a>.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Rows are kept for 180 days (<code>LEDGER_RETENTION_DAYS</code>; <code>0</code> keeps them forever). The <strong>Ledger and audit retention</strong> job removes older rows once an hour. After an upgrade, a banner at the top of the page announces the first purge a week ahead, with the number of rows it will delete.</p><p>Rows are written without delaying the download. If the database is briefly unavailable, a row can be lost; DepGate logs each lost row and counts it in the <code>depgate_ledger_rows_lost_total</code> metric.</p>',20)])])}const w=t(d,[["render",i]]);export{m as __pageData,w as default};
